  function buildPacks(dishId, dishName, photos, singleTiers){
    photos = photos || [];
    const st = singleTiers || [];
    return [
      {
        id: dishId + "-simple",
        name: "Pack Simple",
        icon: "🥘",
        photo: photos[0] || null,
        badge: "Populaire",
        ingredientsBase: [dishName + " (10 boules)", "Arachides", "Oignons, ail", "Écrevisses"],
        complementLabel: "Complément",
        complements: [
          { name: "2 Ngata Miondo", price: 7000, ...(st[0] !== undefined ? {singlePrice: st[0]} : {}) },
          { name: "Autre complément : Bobolo", price: 7500, ...(st[0] !== undefined ? {singlePrice: st[0]} : {}) }
        ]
      },
      {
        id: dishId + "-complet",
        name: "Pack Complet",
        icon: "🍲",
        photo: photos[1] || photos[0] || null,
        badge: "Best-seller",
        ingredientsBase: [dishName + " (10 boules)", "Arachides", "Oignons, ail", "Écrevisses", "Viande avec os (1kg)"],
        complementLabel: "Complément",
        complements: [
          { name: "2 Ngata Miondo", price: 11000, ...(st[1] !== undefined ? {singlePrice: st[1]} : {}) },
          { name: "Autre complément : Bobolo", price: 11000, ...(st[1] !== undefined ? {singlePrice: st[1]} : {}) },
          { name: "Autre complément : Plantains", price: 12000, ...(st[1] !== undefined ? {singlePrice: st[1]} : {}) }
        ]
      },
      {
        id: dishId + "-premium",
        name: "Pack Premium",
        icon: "🍛",
        photo: photos[1] || photos[0] || null,
        badge: "Le plus complet",
        ingredientsBase: [dishName + " (10 boules)", "Arachides", "Oignons, ail", "Écrevisses", "Viande sans os (1kg)"],
        complementLabel: "Complément",
        complements: [
          { name: "2 Ngata Miondo", price: 12000, ...(st[2] !== undefined ? {singlePrice: st[2]} : {}) },
          { name: "Autre complément : Bobolo", price: 12000, ...(st[2] !== undefined ? {singlePrice: st[2]} : {}) },
          { name: "Autre complément : Plantains", price: 12000, ...(st[2] !== undefined ? {singlePrice: st[2]} : {}) }
        ]
      }
    ];
  }

