  // NOTE : les packs Eru et Okok reprennent temporairement les mêmes ingrédients/prix que le Ndolé (placeholder), à remplacer par les vraies infos.

  const qtyState = {};
  dishes.forEach(dish => {
    dish.packs.forEach(p => { qtyState[p.id] = 1; });
    qtyState[dish.customPack.id] = 1;
  });

  const cart = []; // array of {key, label, detail, unitPrice, qty}
  let currentDish = null;
  let currentFormat = 'familial';

  function scalePrice(price){
    if(currentFormat === 'single'){
      return Math.round((price / 3) / 500) * 500;
    }
    return price;
  }

  function complementDisplayPrice(complement){
    if(currentFormat === 'single' && typeof complement.singlePrice === 'number'){
      return complement.singlePrice;
    }
    return scalePrice(complement.price);
  }

  // Certains packs n'ont qu'un seul "complément" générique (prix de base uniquement,
  // sans vrai choix pour le client) : on l'affiche comme "pas de complément" plutôt
  // que comme un menu déroulant à une seule option, ce qui serait trompeur.
  function isGenericComplement(complements){
    return complements.length === 1 && complements[0].name === "Portion standard (6-8 personnes)";
  }

